import{_ as e,c as r,o as p,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"30、【離】 離下離上","description":"周易尚氏學 - 30、【離】 離下離上","frontmatter":{"title":"30、【離】 離下離上","description":"周易尚氏學 - 30、【離】 離下離上"},"headers":[],"relativePath":"classics/shangshi/035.md","filePath":"classics/shangshi/035.md"}'),s={name:"classics/shangshi/035.md"};function t(h,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_30、【離】-離下離上" tabindex="-1">30、【離】 離下離上 <a class="header-anchor" href="#_30、【離】-離下離上" aria-label="Permalink to “30、【離】 離下離上”">​</a></h1><p>乾交坤為坎。坤交乾為離。坎為隱而離則明矣。凡相對之卦。其義皆對。二五中正。故利貞。二五麗於陽中故亨。坤為牛。離得坤中爻。故亦為牛。俞雲。說文牝畜母也。牧牛即母牛。虞翻謂以離為牝牛為借說。豈知左傳昭五年。明雲純離為牛。由是證虞翻未見左氏。</p><p>象曰。離。麗也。日月麗乎天。百穀草木麗乎土。重明以麗乎正。及化成天下。柔麗乎中正。故亨。是以畜牝牛吉也。</p><p>五為天位。離日兌月。象失傳。詳焦氏易詁皆在五。故曰日月麗乎天。禮王制郵罰麗於事。注麗附也。言日月附於天也。二四互巽。為百穀。為草木。而二為地位。故曰麗乎地。從王肅不作土兩象故重明。萬物得日以化成。</p><p>象曰。明兩作。離。大人以繼明照於四方。</p><p>晌明而治。故曰大人。重明。故曰繼。</p><p>初九。履錯然。敬之。句無咎。</p><p>王注。錯然敬慎之貌。處離之始。故宜慎所履以敬為務。避其咎也。按初為震爻。震為履。錯然。蓋又有鄭重不苟之意。故曰敬。以敬之連無咎讀者非。</p><h3 id="象曰。履錯之敬。以闢咎也。" tabindex="-1">象曰。履錯之敬。以闢咎也。 <a class="header-anchor" href="#象曰。履錯之敬。以闢咎也。" aria-label="Permalink to “象曰。履錯之敬。以闢咎也。”">​</a></h3><p>六二。黃離。元吉。</p><p>坤色黃。離得坤中爻。故曰黃離。得中故大吉。</p><h3 id="象曰。黃離元吉。得中道也。" tabindex="-1">象曰。黃離元吉。得中道也。 <a class="header-anchor" href="#象曰。黃離元吉。得中道也。" aria-label="Permalink to “象曰。黃離元吉。得中道也。”">​</a></h3><p>九三。日昃之離。不鼓擊而歌。則大耋之嗟。兇。</p><p>三居離終。故曰日昃。故象曰不可久。此爻全用伏象。伏震為鼓為缶為歌。伏艮為堅。故易林常以艮為壽為老。釋言耋老也。蓋三居下卦之終。時已遲暮。故曰不鼓缶而歌。詩坎其系擊。缶固古樂也。而三居互艮之初。艮為大老？？？。言不及時行樂。則將有衰老之嗟也。震為樂。震反為艮則嗟矣。此與中孚六三之或鼓或罷。或泣或歌。皆正覆象並用。與雜卦震起艮止。兌見巽伏之義同也。而能識此旨者。在古則左傳。在西漢則易林。後則無知者。</p><h3 id="象曰。日昃之離。何可久也。" tabindex="-1">象曰。日昃之離。何可久也。 <a class="header-anchor" href="#象曰。日昃之離。何可久也。" aria-label="Permalink to “象曰。日昃之離。何可久也。”">​</a></h3><p>九四。突如其來如。焚如。死如。棄如。</p><p>九四雖失位。然其兇不至如此之甚。蓋此爻之義。仍取覆象。自覆象失傳。故說者皆莫明其故。離二至四巽。巽順。三至五巽覆。即不順矣。兌剛滷。故突如其來如。突與雲同。亦作充（下　？）。說文雲不順忽出也。從倒子。易曰突如其來如。不孝子突出不容於內也。雲亦作充（下　）者。說文充（下　）下雲。或從倒古文子。即易突字。按古文子作災。倒之即為充（下　）。惠棟校集解。竟改為充（下　）。然說文明曰即易突字。是古本易作突與今同。改作災非也。巽覆故不順。子體倒故曰不孝子。不孝子無所容於世。體離故焚如。兌毀折故死如。棄如。說文棄損也。從充（下　）。充（下　）不孝子也。故匈奴傳。王莽造焚如之刑。如淳雲。焚如死如棄如者。謂不孝子也。不畜於父母。不容於朋友。故燒殺棄之。按如淳及許慎之說。皆與象傳無所容義合。蓋古義如此也。</p><h3 id="象曰。突如其來如。無所容也。" tabindex="-1">象曰。突如其來如。無所容也。 <a class="header-anchor" href="#象曰。突如其來如。無所容也。" aria-label="Permalink to “象曰。突如其來如。無所容也。”">​</a></h3><p>六五。出涕淪若。戚嗟若。吉。</p><p>目汁出曰涕。五離為目。兌為雨水。夬九三。往遇雨。革傳水火相息。水出自目。故曰涕淪。淪說文水別流。言涕被面而支溢也。清儒皆以伏坎為涕。於卦象之神妙全失。兌口為嗟。若者語辭。象本不吉。然而云吉者。以麗於陽中也。</p><h3 id="象曰。六五之吉。麗王公也。" tabindex="-1">象曰。六五之吉。麗王公也。 <a class="header-anchor" href="#象曰。六五之吉。麗王公也。" aria-label="Permalink to “象曰。六五之吉。麗王公也。”">​</a></h3><p>乾為王為公。謂四上。</p><p>上九。王用出徵，有嘉折首，獲匪其醜，無咎。</p><p>此與大有鼎上九義同也。大有上九雲。自天有之。吉無不利。鼎上九雲。大吉。蓋大有鼎中交皆不利。凡中爻不通利者。上九必利。大畜中爻為艮所畜。至上九忽亨。則以上九高出庶物。不為所言也。大有鼎離與大畜理同也。茹敦和雲。離有徵伐象。明夷九三日。南狩（左月）。得其大首。晉上九日。維有伐邑。皆為離上爻。蓋一陽突出兌說之上。而兌為斧鉞。離為甲兵。故曰王用出徵。兌為毀折。乾為首。先儒皆謂坎折坤。則離亦折乾也。皆以中爻故離有殺象。既濟雲東鄰殺牛是也。折首謂殺敵。于思泊雲。虢季盤折首五百。執訊五十。不？（左其右上鳳右下女）股。女多禽折首。執訊。徵之金文。皆謂殺敵。非謂魁首。按於說是也。匪與分古通。周禮地官。凜（？）人以待國之匪頒。注匪讀為分。獲匪其衛者。謂匪頒所獲醜擄於有功。以為奴隸也。</p><h3 id="象曰。王用出徵。以正邦也。" tabindex="-1">象曰。王用出徵。以正邦也。 <a class="header-anchor" href="#象曰。王用出徵。以正邦也。" aria-label="Permalink to “象曰。王用出徵。以正邦也。”">​</a></h3><p>徵正也。折首獲醜。皆正邦之事。邦象未詳。諸家皆以坤為邦。按三至五伏艮。艮為邦。</p>',26)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
